CAS_TYPE = {
"cavitation-pompe": ("Une pompe de forage qui « mange du gravier »", "Sur un site de lavage, une pompe de reprise devient bruyante et le débit baisse un peu chaque semaine. L’équipe ouvre la crépine : elle est à moitié bouchée par des feuilles et du sable. Après nettoyage, le bruit disparaît.", "Un bruit de gravier sur une pompe se cherche d’abord côté aspiration, avant d’accuser la pompe."),
"pompe-garniture-mecanique-fuit": ("La garniture qui fuit après chaque démarrage", "Une pompe de circulation fuit à la garniture quelques jours après chaque redémarrage. On découvre que la pompe tourne quelques secondes à sec au démarrage, car le clapet de pied laisse redescendre l’eau. Le clapet est changé et la nouvelle garniture tient.", "Remplacer une garniture sans chercher pourquoi elle a lâché, c’est souvent la remplacer deux fois."),
"roulement-qui-siffle-ou-gronde": ("Un moteur de ventilation qui change de voix", "Un technicien remarque pendant sa ronde qu’un moteur de ventilation siffle légèrement. Le palier côté ventilateur a pris 15 °C par rapport au mois précédent. Le roulement est changé lors d’un arrêt planifié, avant la casse.", "Un bruit nouveau associé à une hausse de température suffit pour planifier l’intervention."),
"moteur-electrique-qui-chauffe": ("Le moteur qui chauffe seulement l’été", "Un moteur de convoyeur déclenche son thermique les après-midis d’été. Le capot de ventilation est plein de poussière collée : l’air ne passe plus. Après nettoyage, la température redescend nettement.", "Avant de soupçonner le moteur, vérifier qu’il respire."),
"moteur-qui-disjoncte": ("Un disjoncteur moteur qui saute au démarrage", "Un moteur de broyeur fait sauter sa protection à chaque démarrage en charge. L’équipe vide la trémie avant le démarrage : le moteur part sans difficulté. Une procédure de démarrage à vide est mise en place.", "Un déclenchement au démarrage n’est pas toujours un défaut électrique : la charge mécanique compte."),
"groupe-electrogene-ne-demarre-pas": ("Le groupe de secours muet le jour de la coupure", "Lors d’une coupure réseau, le groupe de secours ne démarre pas : le démarreur claque à peine. La batterie a cinq ans et le chargeur était débranché depuis des travaux. Batterie neuve, chargeur rebranché, essai mensuel planifié.", "Un groupe de secours se teste chaque mois, batterie comprise."),
"compresseur-tourne-sans-arret": ("Un compresseur qui tournait la nuit pour rien", "Le compresseur d’un atelier tourne une partie de la nuit alors que tout est arrêté. Une tournée d’écoute trouve une douzaine de fuites sur des raccords rapides. Une fois réparées, le compresseur reste à l’arrêt la nuit.", "Un compresseur qui tourne production arrêtée signale presque toujours des fuites."),
"chambre-froide-temperature-remonte": ("La chambre froide qui remonte en fin de journée", "Une chambre froide positive monte à 7 °C chaque fin de journée. Le joint de porte est déchiré sur 30 cm et la porte reste souvent entrouverte pendant les livraisons. Joint changé et rideau à lanières posé : la température tient.", "La porte et les joints se vérifient avant le groupe frigorifique."),
"courroie-qui-siffle-ou-patine": ("La courroie qui siffle au démarrage", "Un ventilateur d’extraction siffle à chaque démarrage. La flèche de la courroie est le double de la valeur prévue et les flancs sont lustrés. Courroie neuve, tension réglée et recontrôlée après quelques heures de marche.", "Une courroie neuve se retend après rodage."),
"huile-reducteur-laiteuse": ("L’huile devenue café au lait", "Sur un réducteur placé dehors, l’huile devient laiteuse en saison des pluies. Le reniflard était cassé et laissait entrer l’eau. Vidange, reniflard neuf protégé de la pluie, contrôle mensuel de l’aspect de l’huile.", "Une huile laiteuse signale de l’eau : trouver par où elle entre."),
"armoire-electrique-connexion-qui-chauffe": ("Une borne trouvée à la caméra thermique", "Lors d’un contrôle thermographique, une phase d’un départ moteur est 25 °C plus chaude que les deux autres. La borne était mal serrée. Elle est resserrée au couple après consignation et recontrôlée en charge.", "Un écart de température entre phases semblables est un signal clair."),
"ventilateur-qui-vibre": ("Un ventilateur qui vibre après le nettoyage", "Après un nettoyage, un ventilateur se met à vibrer fortement. Une masse d’équilibrage collée sur une pale s’était détachée. La roue est rééquilibrée et la vibration revient à son niveau de référence.", "Une vibration qui apparaît après une intervention a souvent sa cause dans cette intervention."),
"climatisation-ne-refroidit-plus": ("La clim qui souffle tiède dans un bureau", "Dans un bureau, la climatisation souffle de l’air à peine frais. Les filtres de l’unité intérieure sont gris de poussière et l’unité extérieure est encombrée de cartons. Après nettoyage et dégagement, l’air soufflé redevient froid.", "Filtres et unité extérieure d’abord : c’est gratuit et c’est souvent la solution."),
"climatisation-qui-coule": ("L’eau qui coulait sur le bureau", "Une unité murale goutte sur un bureau pendant les journées humides. Le tuyau des condensats est bouché par un dépôt gélatineux. Après rinçage du tuyau, l’eau s’écoule normalement.", "Une clim qui coule a presque toujours une évacuation bouchée."),
"differentiel-qui-saute": ("Le différentiel qui sautait les jours de pluie", "Dans un local, le différentiel saute seulement les jours de forte pluie. En débranchant les circuits un par un, on trouve une prise extérieure où l’eau s’infiltre. La prise est remplacée par un modèle étanche.", "Un différentiel qui saute avec la pluie cherche de l’eau dans un appareil ou une boîte."),
"surpresseur-demarre-sans-arret": ("Le surpresseur qui démarrait toutes les 30 secondes", "Un surpresseur d’immeuble démarre et s’arrête sans cesse. La vessie du ballon n’a plus de pression d’air. Regonflée à la bonne pression, la pompe ne démarre plus que lorsqu’on tire de l’eau.", "Des démarrages trop fréquents usent le moteur : le ballon est le premier suspect."),
"lire-un-spectre-vibratoire": ("Un pic à 1× qui a tout expliqué", "Sur une pompe, la vibration double en un mois. Le spectre montre un pic dominant à la vitesse de rotation, surtout en radial. La roue avait pris un dépôt d’un côté : après nettoyage, le pic retombe.", "Un pic à 1× en radial oriente d’abord vers un balourd."),
"courants-de-palier-variateur": ("Des roulements changés trois fois en un an", "Un moteur piloté par variateur casse ses roulements tous les quatre mois. À l’expertise, les pistes montrent des cannelures régulières. Un roulement isolé et un balai de mise à la terre arrêtent le phénomène.", "Des roulements qui cassent en série sur un moteur à variateur doivent faire penser aux courants de palier."),
"hydraulique-huile-qui-chauffe": ("Une presse qui chauffait l’après-midi", "Une centrale hydraulique dépasse 70 °C en fin de journée. L’échangeur à air est colmaté par la poussière et un limiteur de pression mal réglé renvoie de l’huile en permanence. Échangeur nettoyé et limiteur réglé : la température reste stable.", "Une huile qui chauffe signale de l’énergie perdue quelque part."),
"eau-dans-l-air-comprime": ("L’eau qui sortait des soufflettes", "Dans un atelier, de l’eau sort des soufflettes en saison humide. Le purgeur automatique de la cuve était bloqué fermé et le sécheur by-passé depuis une panne. Purgeur remplacé et sécheur remis en service.", "L’eau dans l’air comprimé se traite à la source : purges et sécheur."),
"pompe-ne-s-amorce-pas": ("La pompe désamorcée chaque matin", "Une pompe d’arrosage est vide chaque matin et ne débite plus. Le clapet de pied ne ferme plus correctement à cause d’un caillou. Clapet nettoyé : la pompe garde son amorçage.", "Une pompe qui se vide à l’arrêt a presque toujours un clapet qui fuit."),
"moteur-bourdonne-ne-demarre-pas": ("Le moteur qui grognait après un orage", "Après un orage, un moteur de pompe triphasé bourdonne sans démarrer. Un fusible du départ moteur a fondu : le moteur ne recevait que deux phases. Fusible remplacé après contrôle de l’isolement, le moteur repart.", "Sur un triphasé qui bourdonne, cherchez la phase manquante."),
"variateur-de-vitesse-en-defaut": ("Le défaut de surtension au freinage", "Un variateur de ventilateur se met en défaut de surtension à chaque arrêt. La rampe de décélération avait été raccourcie pour gagner du temps. Rallongée à sa valeur d’origine, le défaut disparaît.", "Le moment du défaut, en accélération, en marche ou au freinage, oriente le diagnostic."),
"contacteur-qui-vibre-ou-colle": ("Le contacteur qui ronflait le soir", "Un contacteur de pompe ronfle de plus en plus en fin de journée. La tension de commande chute fortement quand d’autres charges démarrent, à cause d’une borne desserrée sur le transformateur de commande. Après resserrage, le ronflement disparaît.", "Un contacteur qui ronfle se diagnostique d’abord par sa tension de bobine."),
"verin-pneumatique-lent-ou-saccade": ("Le vérin qui ralentissait au fil de la journée", "Un vérin d’éjection ralentit au fil de la journée. Le filtre-régulateur du poste est plein d’eau et la pression chute à 4 bar pendant le mouvement. Après purge et nettoyage, le vérin retrouve sa vitesse.", "Mesurez la pression pendant le mouvement, pas à l’arrêt."),
"fuites-air-comprime": ("Une tournée de fuites un samedi matin", "Un samedi, atelier à l’arrêt, deux techniciens font une tournée d’écoute avec de l’eau savonneuse. Ils étiquettent une vingtaine de fuites, surtout sur les raccords rapides. Après réparation, le compresseur tourne nettement moins.", "Une tournée de fuites est l’une des actions les plus rentables d’un atelier."),
"groupe-electrogene-cale-en-charge": ("Le groupe qui calait au démarrage de la clim", "Un groupe électrogène s’effondre dès que la climatisation démarre. Le préfiltre contient de l’eau et le groupe est juste en puissance. Après purge et remplacement des filtres, et avec un démarrage décalé de la clim, le groupe tient.", "Au démarrage, un moteur appelle bien plus que sa puissance nominale."),
"groupe-electrogene-fumee-noire-blanche-bleue": ("La fumée noire qui a révélé un filtre à air", "Un groupe fait une fumée noire épaisse à chaque prise de charge. Le filtre à air est colmaté par la poussière d’un chantier voisin. Filtre changé : la fumée disparaît et le groupe reprend la charge normalement.", "Fumée noire : on cherche d’abord un manque d’air."),
"batterie-qui-ne-tient-pas-la-charge": ("La batterie à 12,5 V qui ne démarrait rien", "Une batterie affiche 12,5 V au repos mais le groupe ne démarre pas. Pendant le démarrage, la tension tombe à 8 V : la batterie est en fin de vie malgré une tension correcte au repos. Elle est remplacée.", "La tension au repos ne suffit pas : mesurez pendant le démarrage."),
"convoyeur-bande-qui-deporte": ("La bande qui partait à gauche en charge", "Une bande se décentre seulement quand elle est chargée. La goulotte de chargement dépose la matière sur le côté droit. Une fois la goulotte recentrée, la bande reste dans l’axe.", "Avant de toucher aux rouleaux, vérifiez où tombe la matière."),
"chaine-de-transmission-qui-saute": ("La chaîne neuve qui a sauté au bout d’un mois", "Une chaîne remplacée saute à nouveau au bout d’un mois. Les pignons, gardés car ils semblaient corrects, avaient des dents en crochet. Chaîne et pignons changés ensemble.", "Une chaîne neuve sur des pignons usés ne tient pas."),
"accouplement-qui-claque": ("La poudre noire sous l’accouplement", "De la poudre noire s’accumule sous l’accouplement d’une pompe. L’alignement est contrôlé : décalage important, et une patte du moteur ne portait pas. Après calage et alignement, l’usure s’arrête.", "De la poudre sous un accouplement est un appel à aligner."),
"roulement-qui-chauffe-apres-graissage": ("Le palier qui chauffait après chaque graissage", "Un palier passe de 50 à 80 °C après chaque graissage hebdomadaire. Le graisseur recevait dix coups de pompe au lieu de deux. Avec la bonne quantité calculée, la température reste stable.", "En graissage, plus n’est pas mieux."),
"reducteur-qui-fuit": ("La fuite qui venait du reniflard", "Un réducteur fuit par ses deux joints de sortie. Le reniflard est bouché par de la poussière collée. Une fois le reniflard nettoyé et les joints changés, la fuite ne revient pas.", "Avant de changer un joint qui fuit, vérifiez le reniflard."),
"reducteur-bruyant": ("Les paillettes sur le bouchon magnétique", "Un réducteur devient bruyant. À la vidange, le bouchon magnétique est couvert de paillettes. L’ouverture planifiée montre un roulement intermédiaire usé, remplacé avant d’abîmer les engrenages.", "Le bouchon magnétique est une petite analyse gratuite."),
"pompe-hydraulique-bruyante": ("La pompe hydraulique qui sifflait au démarrage", "Une pompe hydraulique siffle fortement les matins froids. L’huile, d’une viscosité trop élevée pour la saison, est épaisse au démarrage et le filtre d’aspiration est chargé. Filtre changé et huile conforme à la notice : le bruit disparaît.", "Une pompe hydraulique bruyante a d’abord un problème d’aspiration."),
"verin-hydraulique-qui-descend": ("La table élévatrice qui descendait la nuit", "Une table élévatrice chargée descend de quelques centimètres pendant la nuit. Après isolement du vérin, la dérive continue : les joints de piston fuient. Joints changés, huile filtrée.", "On isole chaque élément pour savoir où passe l’huile."),
"compresseur-ne-demarre-pas": ("Le compresseur qui attendait simplement", "Un compresseur ne démarre pas le matin et l’équipe pense à une panne. La cuve est encore à 7 bar et le pressostat n’enclenche qu’à 6 bar. Il démarre normalement dès que la consommation fait baisser la pression.", "Avant de démonter, lisez le manomètre."),
"compresseur-temperature-haute": ("Le compresseur qui s’arrêtait à 15 h", "Un compresseur à vis s’arrête en alarme température chaque après-midi. Le local n’a pas d’extraction et l’air chaud tourne en rond ; le refroidisseur est gras. Une gaine d’extraction et un nettoyage règlent le problème.", "Un compresseur rejette beaucoup de chaleur : elle doit sortir du local."),
"groupe-froid-coupe-haute-pression": ("Le défaut HP des journées chaudes", "Un groupe froid coupe en haute pression vers 14 h. Le condenseur est couvert de poussière et de pollen. Nettoyé à l’arrêt, il tient toute la journée.", "Le condenseur se nettoie avant la saison chaude, pas pendant la panne."),
"evaporateur-qui-givre": ("L’évaporateur transformé en bloc de glace", "Une chambre froide ne descend plus et l’évaporateur est pris en glace. Une résistance de dégivrage est coupée : le dégivrage ne se faisait plus que d’un côté. Résistance remplacée, dégivrage contrôlé.", "Un bloc de glace signale presque toujours un dégivrage défaillant."),
"moteur-electrique-qui-vibre": ("La vibration qui disparaissait à la coupure", "Un moteur vibre anormalement. Au test de coupure, la vibration disparaît instantanément : la cause est électrique. On trouve un déséquilibre de tension dû à une connexion desserrée en amont.", "Le test de coupure trie en quelques secondes mécanique et électrique."),
"disjoncteur-qui-saute": ("Le disjoncteur de la cuisine d’entreprise", "Dans une petite cuisine, le disjoncteur saute quand la bouilloire, le micro-ondes et la machine à café tournent ensemble. C’est une surcharge : un circuit supplémentaire est créé pour la machine à café.", "Un déclenchement retardé avec plusieurs gros appareils signe une surcharge."),
"prise-ou-cable-qui-chauffe": ("La multiprise fondue sous le bureau", "Dans un bureau, une multiprise alimente un radiateur d’appoint et une autre multiprise. Le plastique commence à fondre et à sentir. Le radiateur est rebranché sur une prise murale et la cascade de multiprises est supprimée.", "Un appareil de chauffage ne se branche jamais sur une multiprise."),
"eclairage-led-qui-clignote": ("Les LED qui brillaient la nuit", "Dans un couloir, les ampoules LED restent faiblement allumées une fois éteintes. L’interrupteur a un voyant lumineux qui laisse passer un petit courant. Remplacé par un interrupteur sans voyant, le phénomène disparaît.", "Une LED qui luit éteinte cherche un petit courant résiduel."),
"vmc-ne-fonctionne-plus": ("La VMC qui n’aspirait plus rien", "Dans un logement, les vitres ruissellent et la bouche de la salle de bain ne retient plus la feuille de papier. Dans les combles, une gaine est écrasée sous un carton. Gaine dégagée, l’aspiration revient.", "Une aspiration faible se cherche dans les bouches et les gaines avant le moteur."),
"groupe-de-securite-chauffe-eau-qui-goutte": ("Le groupe de sécurité qui coulait sans arrêt", "Un groupe de sécurité coule en continu, même chauffe terminée. La pression du réseau mesurée est de 6,5 bar. Un réducteur de pression est posé : le groupe ne goutte plus que pendant la chauffe, comme prévu.", "Un écoulement continu fait d’abord mesurer la pression d’eau."),
"pompe-de-relevage-ne-demarre-plus": ("Le poste de relevage bloqué par des lingettes", "Une alarme de niveau haut sonne au poste de relevage d’un bâtiment. La roue de la pompe est entourée de lingettes. Après nettoyage, la pompe repart ; une affiche est posée dans les sanitaires.", "Les lingettes sont la première cause de panne des pompes de relevage."),
"circulateur-chauffage-bloque": ("Les radiateurs froids du premier jour de chauffe", "Au premier jour de chauffe, la chaudière fonctionne mais les radiateurs restent froids. Le circulateur, immobile tout l’été, est grippé. Débloqué selon la notice du constructeur, il repart et le circuit est purgé.", "Après l’été, le circulateur est le premier suspect."),
}
